var d = tree.root.find_child("DeploymentSummaryDialog", true, false)
var vp = tree.root.get_visible_rect().size
return abs((d.position.y + d.size.y / 2.0) - vp.y / 2.0)

var d = tree.root.find_child("DeploymentSummaryDialog", true, false)
var vp = tree.root.get_visible_rect().size
return vp.y - (d.position.y + d.size.y)

var m = tree.current_scene
var units = []
for uid in GameState.state.units.keys():
	units.append({"unit_id": uid, "name": str(GameState.state.units[uid].get("meta", {}).get("name", uid))})
	if units.size() >= 2:
		break
m._show_battle_shock_confirmation_dialog(units, GameState.get_active_player())
return units.size()

var d = tree.root.find_child("BattleShockConfirmationDialog", true, false)
var vp = tree.root.get_visible_rect().size
return abs((d.position.y + d.size.y / 2.0) - vp.y / 2.0)

var m = tree.current_scene
var units = []
for uid in GameState.state.units.keys():
	units.append({"unit_id": uid, "name": str(GameState.state.units[uid].get("meta", {}).get("name", uid))})
	if units.size() >= 2:
		break
m._show_end_fight_confirmation_dialog(units, GameState.get_active_player())
return units.size()

var d = tree.root.get_node("EndFightConfirmationDialog")
var vp = tree.root.get_visible_rect().size
return abs((d.position.y + d.size.y / 2.0) - vp.y / 2.0)

var d = tree.root.get_node("EndFightConfirmationDialog")
